window.officeBundle = {"date":"2026-11-22","services":{"morning_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"Grace to you and peace from God our Father and the Lord Jesus Christ."},{"line_type":"citation","content":"PHILIPPIANS 1:2"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Venite"},{"line_type":"subheading","content":"O Come"},{"line_type":"rubric","content":"Officiant and People, all standing"},{"line_type":"leader","content":"The earth is the Lord\u2019s for he made it:"},{"line_type":"congregation","content":"O come, let us adore him."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"O come, let us sing unto the Lord; *"},{"line_type":"congregation","content":"let us heartily rejoice in the strength of our salvation."},{"line_type":"congregation","content":"Let us come before his presence with thanksgiving *"},{"line_type":"congregation","content":"and show ourselves glad in him with psalms."},{"line_type":"congregation","content":"For the Lord is a great God *"},{"line_type":"congregation","content":"and a great King above all gods."},{"line_type":"congregation","content":"In his hand are all the depths of the earth, *"},{"line_type":"congregation","content":"and the heights of the hills are his also."},{"line_type":"congregation","content":"The sea is his, for he made it, *"},{"line_type":"congregation","content":"and his hands prepared the dry land."},{"line_type":"congregation","content":"O come, let us worship and fall down, *"},{"line_type":"congregation","content":"and kneel before the Lord our Maker."},{"line_type":"congregation","content":"For he is our God, *"},{"line_type":"congregation","content":"and we are the people of his pasture,"},{"line_type":"congregation","content":"and the sheep of his hand."},{"line_type":"rubric","content":"The following verses may be omitted."},{"line_type":"congregation","content":"Today, if you will hear his voice, harden not your hearts *"},{"line_type":"congregation","content":"as in the provocation, and as in the day of temptation in the wilderness,"},{"line_type":"congregation","content":"When your fathers tested me, *"},{"line_type":"congregation","content":"and put me to the proof, though they had seen my works."},{"line_type":"congregation","content":"Forty years long was I grieved with this generation and said, *"},{"line_type":"congregation","content":"\u201cIt is a people that err in their hearts, for they have not known my ways,\u201d"},{"line_type":"congregation","content":"Of whom I swore in my wrath *"},{"line_type":"congregation","content":"that they should not enter into my rest."},{"line_type":"citation","content":"Psalm 95:1-7, 8-11"},{"line_type":"leader","content":"The earth is the Lord\u2019s for he made it:"},{"line_type":"congregation","content":"O come, let us adore him."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalm Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 59"},{"line_type":"subheading","content":"Eripe me de inimicis"},{"line_type":"leader","content":"Deliver me from my enemies, O God; *","preface":1},{"line_type":"leader","content":"defend me from those who rise up against me."},{"line_type":"congregation","content":"O deliver me from the evildoers, *","preface":2},{"line_type":"congregation","content":"and save me from the bloodthirsty."},{"line_type":"leader","content":"For behold, they lie in wait for my soul; *","preface":3},{"line_type":"leader","content":"the mighty are gathered against me, without any offense or fault of mine, O L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"They run and prepare themselves without cause. *","preface":4},{"line_type":"congregation","content":"Arise therefore to help me, and behold."},{"line_type":"leader","content":"Rise up, O L\u1d0f\u0280\u1d05 God of hosts, O God of Israel, to visit all the nations, *","preface":5},{"line_type":"leader","content":"and be not merciful to those who offend with malicious wickedness."},{"line_type":"congregation","content":"They go to and fro in the evening; *","preface":6},{"line_type":"congregation","content":"they howl like dogs, and run about through the city."},{"line_type":"leader","content":"Behold, they boast with their mouths, and taunts are on their lips, *","preface":7},{"line_type":"leader","content":"for they say, \u201cWho will hear us?\u201d"},{"line_type":"congregation","content":"But you, O L\u1d0f\u0280\u1d05, shall hold them in derision, *","preface":8},{"line_type":"congregation","content":"and you shall laugh all the nations to scorn."},{"line_type":"leader","content":"My strength I will ascribe unto you, *","preface":9},{"line_type":"leader","content":"for you are the God of my refuge."},{"line_type":"congregation","content":"God shows me his plenteous goodness, *","preface":10},{"line_type":"congregation","content":"and God shall let me look in triumph upon my enemies."},{"line_type":"leader","content":"Slay them not, lest my people forget it, *","preface":11},{"line_type":"leader","content":"but scatter them abroad by your might, and put them down, O Lord our shield."},{"line_type":"congregation","content":"For the sin of their mouth, and for the words of their lips, they shall be taken in their pride, *","preface":12},{"line_type":"congregation","content":"because their talk is cursing and lies."},{"line_type":"leader","content":"Consume them in your wrath; consume them, that they may perish, *","preface":13},{"line_type":"leader","content":"and know that it is God who rules in Jacob, and unto the ends of the world."},{"line_type":"congregation","content":"In the evening they will return, *","preface":14},{"line_type":"congregation","content":"howl like dogs, and run about through the city."},{"line_type":"leader","content":"They will run here and there for meat *","preface":15},{"line_type":"leader","content":"and growl if they are not satisfied."},{"line_type":"congregation","content":"As for me, I will sing of your power, and will praise your mercy early in the morning, *","preface":16},{"line_type":"congregation","content":"for you have been my defense and refuge in the day of my trouble."},{"line_type":"leader","content":"Unto you, O my strength, will I sing, *","preface":17},{"line_type":"leader","content":"for you, O God, are my refuge, and my merciful God."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Judith 16"},{"line_type":"reader","content":"A reading from the Book of Judith, beginning with the sixteenth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_0f1223d9-282a-56aa-a78e-92c231be60a9'></span><p><span class=\"cc vnumVis\">16</span>Then Judith began to sing this thanksgiving in all Israel, and all the people sang after her this song of praise. <sup>2\u00a0</sup>And Judith said, Begin unto my God with timbrels, sing unto my Lord with cymbals: tune unto him a new psalm: exalt him, and call upon his name. <sup>3\u00a0</sup>For God breaketh the battles: for among the camps in the midst of the people he hath delivered me out of the hands of them that persecuted me. <sup>4\u00a0</sup>Assur came out of the mountains from the north, he came with ten thousands of his army, the multitude whereof stopped the torrents, and their horsemen have covered the hills. <sup>5\u00a0</sup>He bragged that he would burn up my borders, and kill my young men with the sword, and dash the sucking children against the ground, and make mine infants as a prey, and my virgins as a spoil. <sup>6\u00a0</sup>But the Almighty Lord hath disappointed them by the hand of a woman. <sup>7\u00a0</sup>For the mighty one did not fall by the young men, neither did the sons of the Titans smite him, nor high giants set upon him: but Judith the daughter of Merari weakened him with the beauty of her countenance. <sup>8\u00a0</sup>For she put off the garment of her widowhood for the exaltation of those that were oppressed in Israel, and anointed her face with ointment, and bound her hair in a tire, and took a linen garment to deceive him. <sup>9\u00a0</sup>Her sandals ravished his eyes, her beauty took his mind prisoner, and the fauchion passed through his neck. <sup>10\u00a0</sup>The Persians quaked at her boldness, and the Medes were daunted at her hardiness. <sup>11\u00a0</sup>Then my afflicted shouted for joy, and my weak ones cried aloud; but they were astonished: these lifted up their voices, but they were overthrown. <sup>12\u00a0</sup>The sons of the damsels have pierced them through, and wounded them as fugatives\u2019 children: they perished by the battle of the Lord. <sup>13\u00a0</sup>I will sing unto the Lord a new song: O Lord, thou art great and glorious, wonderful in strength, and invincible. <sup>14\u00a0</sup>Let all creatures serve thee: for thou spakest, and they were made, thou didst send forth thy spirit, and it created them, and there is none that can resist thy voice. <sup>15\u00a0</sup>For the mountains shall be moved from their foundations with the waters, the rocks shall melt as wax at thy presence: yet thou art merciful to them that fear thee. <sup>16\u00a0</sup>For all sacrifice is too little for a sweet savour unto thee, and all the fat is not sufficient for thy burnt offering: but he that feareth the Lord is great at all times. <sup>17\u00a0</sup>Woe to the nations that rise up against my kindred! the Lord Almighty will take vengeance of them in the day of judgment, in putting fire and worms in their flesh; and they shall feel them, and weep for ever. <sup>18\u00a0</sup>Now as soon as they entered into Jerusalem, they worshipped the Lord; and as soon as the people were purified, they offered their burnt offerings, and their free offerings, and their gifts. <sup>19\u00a0</sup>Judith also dedicated all the stuff of Holofernes, which the people had given her, and gave the canopy, which she had taken out of his bedchamber, for a gift unto the Lord. <sup>20\u00a0</sup>So the people continued feasting in Jerusalem before the sanctuary for the space of three months and Judith remained with them. <sup>21\u00a0</sup>After this time every one returned to his own inheritance, and Judith went to Bethulia, and remained in her own possession, and was in her time honourable in all the country. <sup>22\u00a0</sup>And many desired her, but none knew her all the days of her life, after that Manasses her husband was dead, and was gathered to his people. <sup>23\u00a0</sup>But she increased more and more in honour, and waxed old in her husband\u2019s house, being an hundred and five years old, and made her maid free; so she died in Bethulia: and they buried her in the cave of her husband Manasses. <sup>24\u00a0</sup>And the house of Israel lamented her seven days: and before she died, she did distribute her goods to all them that were nearest of kindred to Manasses her husband, and to them that were the nearest of her kindred. <sup>25\u00a0</sup>And there was none that made the children of Israel any more afraid in the days of Judith, nor a long time after her death.</p>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"Here ends the Reading."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"TE DEUM LAUDAMUS"},{"line_type":"subheading","content":"We Praise You, O God"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"We praise you, O God; we acclaim you as Lord; *"},{"line_type":"congregation","content":"all creation worships you, the Father everlasting."},{"line_type":"congregation","content":"To you all angels, all the powers of heaven, *"},{"line_type":"congregation","content":"the cherubim and seraphim, sing in endless praise:"},{"line_type":"congregation","content":"Holy, Holy, Holy, Lord God of power and might, *"},{"line_type":"congregation","content":"heaven and earth are full of your glory."},{"line_type":"congregation","content":"The glorious company of apostles praise you. *"},{"line_type":"congregation","content":"The noble fellowship of prophets praise you."},{"line_type":"congregation","content":"The white-robed army of martyrs praise you. *"},{"line_type":"congregation","content":"Throughout the world the holy Church acclaims you:"},{"line_type":"congregation","content":"Father, of majesty unbounded,"},{"line_type":"congregation","content":"your true and only Son, worthy of all praise, *"},{"line_type":"congregation","content":"and the Holy Spirit, advocate and guide."},{"line_type":"congregation","content":"You, Christ, are the king of glory, *"},{"line_type":"congregation","content":"the eternal Son of the Father."},{"line_type":"congregation","content":"When you took our flesh to set us free *"},{"line_type":"congregation","content":"you humbly chose the Virgin\u2019s womb."},{"line_type":"congregation","content":"You overcame the sting of death *"},{"line_type":"congregation","content":"and opened the kingdom of heaven to all believers."},{"line_type":"congregation","content":"You are seated at God\u2019s right hand in glory. *"},{"line_type":"congregation","content":"We believe that you will come to be our judge."},{"line_type":"congregation","content":"Come then, Lord, and help your people, *"},{"line_type":"congregation","content":"bought with the price of your own blood,"},{"line_type":"congregation","content":"and bring us with your saints *"},{"line_type":"congregation","content":"to glory everlasting."},{"line_type":"rubric","content":"The following verses may be omitted"},{"line_type":"congregation","content":"Save your people, Lord, and bless your inheritance;*"},{"line_type":"congregation","content":"govern and uphold them now and always."},{"line_type":"congregation","content":"Day by day we bless you; *"},{"line_type":"congregation","content":"we praise your Name for ever."},{"line_type":"congregation","content":"Keep us today, Lord, from all sin; *"},{"line_type":"congregation","content":"have mercy on us, Lord, have mercy."},{"line_type":"congregation","content":"Lord, show us your love and mercy, *"},{"line_type":"congregation","content":"for we have put our trust in you."},{"line_type":"congregation","content":"In you, Lord, is our hope; *"},{"line_type":"congregation","content":"let us never be put to shame."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Acts 19:21-41"},{"line_type":"reader","content":"A reading from the Acts of the Apostles, beginning with the nineteenth chapter, the twenty-first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_c731ceec-fc92-5628-8dde-5ca7dda09309'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p><span class=\"text Acts-19-21\" id=\"en-AKJV-27607\"><sup class=\"versenum\">21\u00a0</sup>After these things were ended, Paul purposed in the spirit, when he had passed through Macedonia and Achaia, to go to Jerusalem, saying, After I have been there, I must also see Rome. </span> <span class=\"text Acts-19-22\" id=\"en-AKJV-27608\"><sup class=\"versenum\">22\u00a0</sup>So he sent into Macedonia two of them that ministered unto him, Timotheus and Erastus; but he himself stayed in Asia for a season.</span></p><span data-line-id='secondreading_b288e10d-bb24-515d-ac36-7e1f84fbf3e8'></span> <p><span class=\"text Acts-19-23\" id=\"en-AKJV-27609\"><sup class=\"versenum\">23\u00a0</sup>And the same time there arose no small stir about that way. </span> <span class=\"text Acts-19-24\" id=\"en-AKJV-27610\"><sup class=\"versenum\">24\u00a0</sup>For a certain man named Demetrius, a silversmith, which made silver shrines for Diana, brought no small gain unto the craftsmen; </span> <span class=\"text Acts-19-25\" id=\"en-AKJV-27611\"><sup class=\"versenum\">25\u00a0</sup>whom he called together with the workmen of like occupation, and said, Sirs, ye know that by this craft we have our wealth. </span> <span class=\"text Acts-19-26\" id=\"en-AKJV-27612\"><sup class=\"versenum\">26\u00a0</sup>Moreover ye see and hear, that not alone at Ephesus, but almost throughout all Asia, this Paul hath persuaded and turned away much people, saying that they be no gods, which are made with hands: </span> <span class=\"text Acts-19-27\" id=\"en-AKJV-27613\"><sup class=\"versenum\">27\u00a0</sup>so that not only this our craft is in danger to be set at nought; but also that the temple of the great goddess Diana should be despised, and her magnificence should be destroyed, whom all Asia and the world worshippeth. </span> <span class=\"text Acts-19-28\" id=\"en-AKJV-27614\"><sup class=\"versenum\">28\u00a0</sup>And when they heard these sayings, they were full of wrath, and cried out, saying, Great is Diana of the Ephesians. </span> <span class=\"text Acts-19-29\" id=\"en-AKJV-27615\"><sup class=\"versenum\">29\u00a0</sup>And the whole city was filled with confusion: and having caught Gaius and Aristarchus, men of Macedonia, Paul\u2019s companions in travel, they rushed with one accord into the theatre. </span> <span class=\"text Acts-19-30\" id=\"en-AKJV-27616\"><sup class=\"versenum\">30\u00a0</sup>And when Paul would have entered in unto the people, the disciples suffered him not. </span> <span class=\"text Acts-19-31\" id=\"en-AKJV-27617\"><sup class=\"versenum\">31\u00a0</sup>And certain of the chief of Asia, which were his friends, sent unto him, desiring him that he would not adventure himself into the theatre. </span> <span class=\"text Acts-19-32\" id=\"en-AKJV-27618\"><sup class=\"versenum\">32\u00a0</sup>Some therefore cried one thing, and some another: for the assembly was confused; and the more part knew not wherefore they were come together. </span> <span class=\"text Acts-19-33\" id=\"en-AKJV-27619\"><sup class=\"versenum\">33\u00a0</sup>And they drew Alexander out of the multitude, the Jews putting him forward. And Alexander beckoned with the hand, and would have made his defence unto the people. </span> <span class=\"text Acts-19-34\" id=\"en-AKJV-27620\"><sup class=\"versenum\">34\u00a0</sup>But when they knew that he was a Jew, all with one voice about the space of two hours cried out, Great is Diana of the Ephesians.</span></p><span data-line-id='secondreading_a4475226-a6ce-5b1f-ac85-3c8a60ead32b'></span> <p><span class=\"text Acts-19-35\" id=\"en-AKJV-27621\"><sup class=\"versenum\">35\u00a0</sup>And when the townclerk had appeased the people, he said, Ye men of Ephesus, what man is there that knoweth not how that the city of the Ephesians is a worshipper of the great goddess Diana, and of the image which fell down from Jupiter? </span> <span class=\"text Acts-19-36\" id=\"en-AKJV-27622\"><sup class=\"versenum\">36\u00a0</sup>Seeing then that these things cannot be spoken against, ye ought to be quiet, and to do nothing rashly. </span> <span class=\"text Acts-19-37\" id=\"en-AKJV-27623\"><sup class=\"versenum\">37\u00a0</sup>For ye have brought hither these men, which are neither robbers of churches, nor yet blasphemers of your goddess. </span> <span class=\"text Acts-19-38\" id=\"en-AKJV-27624\"><sup class=\"versenum\">38\u00a0</sup>Wherefore if Demetrius, and the craftsmen which are with him, have a matter against any man, the law is open, and there are deputies: let them implead one another. </span> <span class=\"text Acts-19-39\" id=\"en-AKJV-27625\"><sup class=\"versenum\">39\u00a0</sup>But if ye enquire any thing concerning other matters, it shall be determined in a lawful assembly. </span> <span class=\"text Acts-19-40\" id=\"en-AKJV-27626\"><sup class=\"versenum\">40\u00a0</sup>For we are in danger to be called in question for this day\u2019s uproar, there being no cause whereby we may give an account of this concourse. </span> <span class=\"text Acts-19-41\" id=\"en-AKJV-27627\"><sup class=\"versenum\">41\u00a0</sup>And when he had thus spoken, he dismissed the assembly.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"BENEDICTUS"},{"line_type":"subheading","content":"The Song of Zechariah"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Blessed be the Lord, the God of Israel; *"},{"line_type":"congregation","content":"he has come to his people and set them free."},{"line_type":"congregation","content":"He has raised up for us a mighty savior, *"},{"line_type":"congregation","content":"born of the house of his servant David."},{"line_type":"congregation","content":"Through his holy prophets he promised of old"},{"line_type":"congregation","content":"that he would save us from our enemies, *"},{"line_type":"congregation","content":"from the hands of all who hate us."},{"line_type":"congregation","content":"He promised to show mercy to our fathers *"},{"line_type":"congregation","content":"and to remember his holy covenant."},{"line_type":"congregation","content":"This was the oath he swore to our father Abraham, *"},{"line_type":"congregation","content":"to set us free from the hands of our enemies,"},{"line_type":"congregation","content":"Free to worship him without fear, *"},{"line_type":"congregation","content":"holy and righteous in his sight"},{"line_type":"congregation","content":"all the days of our life."},{"line_type":"congregation","content":"You, my child, shall be called the prophet of the Most High, *"},{"line_type":"congregation","content":"for you will go before the Lord to prepare his way,"},{"line_type":"congregation","content":"To give his people knowledge of salvation *"},{"line_type":"congregation","content":"by the forgiveness of their sins."},{"line_type":"congregation","content":"In the tender compassion of our God *"},{"line_type":"congregation","content":"the dawn from on high shall break upon us,"},{"line_type":"congregation","content":"To shine on those who dwell in darkness"},{"line_type":"congregation","content":"and in the shadow of death, *"},{"line_type":"congregation","content":"and to guide our feet into the way of peace."},{"line_type":"citation","content":"LUKE 1:68-79"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"The Last Sunday after Pentecost: Christ the King"},{"line_type":"leader","content":"Almighty and everlasting God, whose will it is to restore all things in your well-beloved Son, the King of kings and Lord of lords: Mercifully grant that the peoples of the earth, divided and enslaved by sin, may be freed and brought together under his most gracious rule; who lives and reigns with you and the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Cecilia, Martyr at Rome, c. 230"},{"line_type":"leader","content":"Almighty God, you gave your servant Cecilia boldness to confess the Name of our Savior Jesus Christ before the rulers of this world, and courage to die for this faith: Grant that we may always be ready to give a reason for the hope that is in us, and to suffer gladly for the sake of our Lord Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Strength to Await Christ's Return"},{"line_type":"subheading","content":"Sunday"},{"line_type":"leader","content":"O God our King, by the resurrection of your Son Jesus Christ on the first day of the week, you conquered sin, put death to flight, and gave us the hope of everlasting life: Redeem all our days by this victory; forgive our sins, banish our fears, make us bold to praise you and to do your will; and steel us to wait for the consummation of your kingdom on the last great Day; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"O God, you have made of one blood all the peoples of the earth, and sent your blessed Son to preach peace to those who are far off and to those who are near: Grant that people everywhere may seek after you and find you; bring the nations into your fold; pour out your Spirit upon all flesh; and hasten the coming of your kingdom; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"2 CORINTHIANS 13:14"}]}],"midday_prayer":[{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 119:105-112"},{"line_type":"subheading","content":"Beati immaculati"},{"line_type":"leader","content":"Your word is a lantern to my feet *","preface":105},{"line_type":"leader","content":"and a light upon my path."},{"line_type":"congregation","content":"I have sworn and am steadfastly purposed *","preface":106},{"line_type":"congregation","content":"to keep your righteous judgments."},{"line_type":"leader","content":"I am troubled above measure; *","preface":107},{"line_type":"leader","content":"revive me, O L\u1d0f\u0280\u1d05, according to your word."},{"line_type":"congregation","content":"Let the freewill offerings of my mouth please you, O L\u1d0f\u0280\u1d05; *","preface":108},{"line_type":"congregation","content":"and teach me your judgments."},{"line_type":"leader","content":"My life is always in my hand, *","preface":109},{"line_type":"leader","content":"yet I do not forget your law."},{"line_type":"congregation","content":"The ungodly have laid a snare for me, *","preface":110},{"line_type":"congregation","content":"yet I have not strayed from your commandments."},{"line_type":"leader","content":"Your testimonies have I claimed as my heritage for ever, *","preface":111},{"line_type":"leader","content":"and why? They are the very joy of my heart."},{"line_type":"congregation","content":"I have applied my heart to fulfill your statutes always, *","preface":112},{"line_type":"congregation","content":"even unto the end. Samekh"},{"line_type":"heading","content":"Psalm 121"},{"line_type":"subheading","content":"Levavi oculos"},{"line_type":"leader","content":"I will lift up my eyes unto the hills; *","preface":1},{"line_type":"leader","content":"from whence comes my help?"},{"line_type":"congregation","content":"My help comes from the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"who has made heaven and earth."},{"line_type":"leader","content":"He will not let your foot be moved, *","preface":3},{"line_type":"leader","content":"and he who keeps you will not sleep."},{"line_type":"congregation","content":"Behold, he who keeps Israel *","preface":4},{"line_type":"congregation","content":"shall neither slumber nor sleep."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 himself is your keeper; *","preface":5},{"line_type":"leader","content":"the L\u1d0f\u0280\u1d05 is your defense upon your right hand,"},{"line_type":"congregation","content":"So that the sun shall not burn you by day, *","preface":6},{"line_type":"congregation","content":"neither the moon by night."},{"line_type":"leader","content":"The L\u1d0f\u0280\u1d05 shall preserve you from all evil; *","preface":7},{"line_type":"leader","content":"indeed, it is he who shall keep your soul."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 shall preserve your going out and your coming in, *","preface":8},{"line_type":"congregation","content":"from this time forth for evermore."},{"line_type":"heading","content":"Psalm 124"},{"line_type":"subheading","content":"Nisi quia Dominus"},{"line_type":"leader","content":"If the L\u1d0f\u0280\u1d05 himself had not been on our side, now may Israel say: *","preface":1},{"line_type":"leader","content":"if the L\u1d0f\u0280\u1d05 himself had not been on our side, when men rose up against us,"},{"line_type":"congregation","content":"Then would they have swallowed us up alive, *","preface":2},{"line_type":"congregation","content":"when they were so wrathfully displeased with us;"},{"line_type":"leader","content":"Then the waters would have drowned us, and the torrent gone over us; *","preface":3},{"line_type":"leader","content":"then the raging waters would have gone clean over us."},{"line_type":"congregation","content":"But praised be the L\u1d0f\u0280\u1d05, *","preface":4},{"line_type":"congregation","content":"who has not given us over to be prey for their teeth."},{"line_type":"leader","content":"We escaped like a bird out of the snare of the fowler; *","preface":5},{"line_type":"leader","content":"the snare is broken, and we have been delivered."},{"line_type":"congregation","content":"Our help is in the Name of the L\u1d0f\u0280\u1d05, *","preface":6},{"line_type":"congregation","content":"the maker of heaven and earth."},{"line_type":"heading","content":"Psalm 126"},{"line_type":"subheading","content":"In convertendo"},{"line_type":"leader","content":"When the L\u1d0f\u0280\u1d05 overturned the captivity of Zion, *","preface":1},{"line_type":"leader","content":"then were we like those who dream."},{"line_type":"congregation","content":"Then was our mouth filled with laughter *","preface":2},{"line_type":"congregation","content":"and our tongue with shouts of joy."},{"line_type":"leader","content":"Then they said among the nations, *","preface":3},{"line_type":"leader","content":"\u201cThe L\u1d0f\u0280\u1d05 has done great things for them.\u201d"},{"line_type":"congregation","content":"Indeed, the L\u1d0f\u0280\u1d05 has done great things for us already, *","preface":4},{"line_type":"congregation","content":"whereof we rejoice."},{"line_type":"leader","content":"Overturn our captivity, O L\u1d0f\u0280\u1d05, *","preface":5},{"line_type":"leader","content":"as when streams refresh the deserts of the south."},{"line_type":"congregation","content":"Those who sow in tears *","preface":6},{"line_type":"congregation","content":"shall reap with songs of joy."},{"line_type":"leader","content":"He who goes on his way weeping and bears good seed *","preface":7},{"line_type":"leader","content":"shall doubtless come again with joy, and bring his sheaves with him."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"Jesus said, \u201cNow is the judgment of this world; now will the ruler of this world be cast out. And I, when I am lifted up from the earth, will draw all people to myself.\u201d"},{"line_type":"citation","content":"JOHN 12:31-32"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"A meditation, silent or spoken, may follow."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"I will bless the Lord at all times."},{"line_type":"congregation_dialogue","content":"His praise shall continually be in my mouth."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Blessed Savior, at this hour you hung upon the Cross, stretching out your loving arms: Grant that all the peoples of the earth may look to you and be saved; for your tender mercies\u2019 sake."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Pour your grace into our hearts, O Lord, that we who have known the incarnation of your Son Jesus Christ, announced by an angel to the Virgin Mary, may by his Cross and passion be brought to the glory of his resurrection; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."}]}],"evening_prayer":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"leader","content":"Lord, I have loved the habitation of your house and the place where your honor dwells."},{"line_type":"citation","content":"PSALM 26:8"}]},{"name":"Confession of Sin","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant says to the People"},{"line_type":"leader","content":"Let us humbly confess our sins to Almighty God."},{"line_type":"rubric","content":"Silence is kept. All kneeling, the Officiant and People say"},{"line_type":"congregation","content":"Almighty and most merciful Father,"},{"line_type":"congregation","content":"we have erred and strayed from your ways like lost sheep."},{"line_type":"congregation","content":"We have followed too much the devices and desires"},{"line_type":"congregation","content":"of our own hearts."},{"line_type":"congregation","content":"We have offended against your holy laws."},{"line_type":"congregation","content":"We have left undone those things which we ought to have done,"},{"line_type":"congregation","content":"and we have done those things which we ought not"},{"line_type":"congregation","content":"to have done;"},{"line_type":"congregation","content":"and apart from your grace, there is no health in us."},{"line_type":"congregation","content":"O Lord, have mercy upon us."},{"line_type":"congregation","content":"Spare all those who confess their faults."},{"line_type":"congregation","content":"Restore all those who are penitent, according to your promises"},{"line_type":"congregation","content":"declared to all people in Christ Jesus our Lord."},{"line_type":"congregation","content":"And grant, O most merciful Father, for his sake,"},{"line_type":"congregation","content":"that we may now live a godly, righteous, and sober life,"},{"line_type":"congregation","content":"to the glory of your holy Name. Amen."},{"line_type":"rubric","content":"A Deacon or layperson remains kneeling and prays"},{"line_type":"leader","content":"Grant to your faithful people, merciful Lord, pardon and peace; that we may be cleansed from all our sins, and serve you with a quiet mind; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Preces","lines":[{"line_type":"heading","content":"The Preces"},{"line_type":"rubric","content":"All stand."},{"line_type":"leader_dialogue","content":"O Lord, open our lips;"},{"line_type":"congregation_dialogue","content":"And our mouth shall proclaim your praise."},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"leader_dialogue","content":"Praise the Lord."},{"line_type":"congregation_dialogue","content":"The Lord\u2019s Name be praised."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"PHOS HILARON"},{"line_type":"subheading","content":"O Gladsome Light"},{"line_type":"congregation","content":"O gladsome light,"},{"line_type":"congregation","content":"pure brightness of the everliving Father in heaven, *"},{"line_type":"congregation","content":"O Jesus Christ, holy and blessed!"},{"line_type":"congregation","content":"Now as we come to the setting of the sun,"},{"line_type":"congregation","content":"and our eyes behold the vesper light, *"},{"line_type":"congregation","content":"we sing your praises, O God: Father, Son, and Holy Spirit."},{"line_type":"congregation","content":"You are worthy at all times to be praised by happy voices, *"},{"line_type":"congregation","content":"O Son of God, O Giver of Life,"},{"line_type":"congregation","content":"and to be glorified through all the worlds."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms Appointed"},{"line_type":"subheading","content":"Sixty Day Cycle"},{"line_type":"heading","content":"Psalm 63"},{"line_type":"subheading","content":"Deus, Deus meus"},{"line_type":"leader","content":"O God, you are my God; *","preface":1},{"line_type":"leader","content":"early will I seek you."},{"line_type":"congregation","content":"My soul thirsts for you, my flesh also longs after you, *","preface":2},{"line_type":"congregation","content":"in a barren and dry land where there is no water."},{"line_type":"leader","content":"Thus I have looked upon you in your holy place, *","preface":3},{"line_type":"leader","content":"that I might behold your power and glory."},{"line_type":"congregation","content":"For your loving-kindness is better than life itself; *","preface":4},{"line_type":"congregation","content":"my lips shall praise you."},{"line_type":"leader","content":"As long as I live I will magnify you, *","preface":5},{"line_type":"leader","content":"and lift up my hands in your Name."},{"line_type":"congregation","content":"My soul shall be satisfied, as with marrow and fatness, *","preface":6},{"line_type":"congregation","content":"when my mouth praises you with joyful lips."},{"line_type":"leader","content":"When I remember you on my bed, *","preface":7},{"line_type":"leader","content":"I meditate on you in the watches of the night."},{"line_type":"congregation","content":"Because you have been my helper, *","preface":8},{"line_type":"congregation","content":"therefore under the shadow of your wings I will rejoice."},{"line_type":"leader","content":"My soul clings to you; *","preface":9},{"line_type":"leader","content":"your right hand has upheld me."},{"line_type":"congregation","content":"Those who seek to destroy my life *","preface":10},{"line_type":"congregation","content":"shall go down into the earth."},{"line_type":"leader","content":"Let them fall upon the edge of the sword, *","preface":11},{"line_type":"leader","content":"that they may be a portion for jackals."},{"line_type":"congregation","content":"But the King shall rejoice in God; all those who swear by him shall be commended, *","preface":12},{"line_type":"congregation","content":"for the mouth of those who speak lies shall be stopped."},{"line_type":"heading","content":"Psalm 64"},{"line_type":"subheading","content":"Exaudi, Deus"},{"line_type":"leader","content":"Hear my voice, O God, in my prayer; *","preface":1},{"line_type":"leader","content":"preserve my life from fear of the enemy."},{"line_type":"congregation","content":"Hide me from the gathering together of the wicked, *","preface":2},{"line_type":"congregation","content":"and from the tumult of evildoers,"},{"line_type":"leader","content":"Who have whet their tongue like a sword, *","preface":3},{"line_type":"leader","content":"and shoot out their arrows, even bitter words,"},{"line_type":"congregation","content":"That they may secretly shoot at the one who is blameless; *","preface":4},{"line_type":"congregation","content":"suddenly do they shoot him, and fear not."},{"line_type":"leader","content":"They hold fast to their evil purpose, *","preface":5},{"line_type":"leader","content":"and discuss among themselves how they may lay snares, and say that no one shall see them."},{"line_type":"congregation","content":"They imagine wickedness, and practice a cunning plot; *","preface":6},{"line_type":"congregation","content":"for the human heart and mind are very deep."},{"line_type":"leader","content":"But God shall suddenly shoot at them with a swift arrow, *","preface":7},{"line_type":"leader","content":"and they shall be wounded."},{"line_type":"congregation","content":"Indeed, their own tongues shall make them fall, *","preface":8},{"line_type":"congregation","content":"so that all who see them shall laugh them to scorn."},{"line_type":"leader","content":"And all shall fear and tell what God has done, *","preface":9},{"line_type":"leader","content":"for they shall perceive that it is his work."},{"line_type":"congregation","content":"The righteous shall rejoice in the L\u1d0f\u0280\u1d05 and put their trust in him, *","preface":10},{"line_type":"congregation","content":"and all who are true of heart shall be glad."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"First Reading","lines":[{"line_type":"heading","content":"The First Lesson"},{"line_type":"subheading","content":"Isaiah 35"},{"line_type":"reader","content":"A reading from the Prophet Isaiah, beginning with the thirty-fifth chapter, the first verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='firstreading_19f31fef-ed2a-58b8-8e7c-edde26e460a2'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<div class=\"poetry top-1\"><p class=\"line\"><span class=\"chapter-2\"><span class=\"text Isa-35-1\" id=\"en-AKJV-18322\"><span class=\"chapternum\">35\u00a0</span>The wilderness and the solitary place shall be glad for them;</span></span><br/><span class=\"text Isa-35-1\">and the desert shall rejoice, and blossom as the rose.</span><br/><span class=\"text Isa-35-2\" id=\"en-AKJV-18323\"><sup class=\"versenum\">2\u00a0</sup>It shall blossom abundantly,</span><br/><span class=\"text Isa-35-2\">and rejoice even with joy and singing:</span><br/><span class=\"text Isa-35-2\">the glory of Lebanon shall be given unto it,</span><br/><span class=\"text Isa-35-2\">the excellency of Carmel and Sharon,</span><br/><span class=\"text Isa-35-2\">they shall see the glory of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span>,</span><br/><span class=\"text Isa-35-2\">and the excellency of our God.</span></p><span data-line-id='firstreading_2e090f76-a8de-583b-84bd-034574829d4b'></span></div> <div class=\"poetry top-1\"><p class=\"line\"><span class=\"text Isa-35-3\" id=\"en-AKJV-18324\"><sup class=\"versenum\">3\u00a0</sup>Strengthen ye the weak hands,</span><br/><span class=\"text Isa-35-3\">and confirm the feeble knees.</span><br/><span class=\"text Isa-35-4\" id=\"en-AKJV-18325\"><sup class=\"versenum\">4\u00a0</sup>Say to them that are of a fearful heart,</span><br/><span class=\"text Isa-35-4\">Be strong, fear not:</span><br/><span class=\"text Isa-35-4\">behold, your God will come with vengeance,</span><br/><span class=\"text Isa-35-4\">even God with a recompence;</span><br/><span class=\"text Isa-35-4\">he will come and save you.</span><br/><span class=\"text Isa-35-5\" id=\"en-AKJV-18326\"><sup class=\"versenum\">5\u00a0</sup>Then the eyes of the blind shall be opened,</span><br/><span class=\"text Isa-35-5\">and the ears of the deaf shall be unstopped.</span><br/><span class=\"text Isa-35-6\" id=\"en-AKJV-18327\"><sup class=\"versenum\">6\u00a0</sup>Then shall the lame man leap as an hart,</span><br/><span class=\"text Isa-35-6\">and the tongue of the dumb sing:</span><br/><span class=\"text Isa-35-6\">for in the wilderness shall waters break out,</span><br/><span class=\"text Isa-35-6\">and streams in the desert.</span><br/><span class=\"text Isa-35-7\" id=\"en-AKJV-18328\"><sup class=\"versenum\">7\u00a0</sup>And the parched ground shall become a pool,</span><br/><span class=\"text Isa-35-7\">and the thirsty land springs of water:</span><br/><span class=\"text Isa-35-7\">in the habitation of dragons, where each lay,</span><br/><span class=\"text Isa-35-7\">shall be grass with reeds and rushes.</span><br/><span class=\"text Isa-35-8\" id=\"en-AKJV-18329\"><sup class=\"versenum\">8\u00a0</sup>And an highway shall be there, and a way,</span><br/><span class=\"text Isa-35-8\">and it shall be called The way of holiness;</span><br/><span class=\"text Isa-35-8\">the unclean shall not pass over it; but it shall be for those:</span><br/><span class=\"text Isa-35-8\">the wayfaring men, though fools, shall not err therein.</span><br/><span class=\"text Isa-35-9\" id=\"en-AKJV-18330\"><sup class=\"versenum\">9\u00a0</sup>No lion shall be there,</span><br/><span class=\"text Isa-35-9\">nor any ravenous beast shall go up thereon,</span><br/><span class=\"text Isa-35-9\">it shall not be found there;</span><br/><span class=\"text Isa-35-9\">but the redeemed shall walk there:</span><br/><span class=\"text Isa-35-10\" id=\"en-AKJV-18331\"><sup class=\"versenum\">10\u00a0</sup>and the ransomed of the <span class=\"small-caps\" style=\"font-variant: small-caps\">Lord</span> shall return,</span><br/><span class=\"text Isa-35-10\">and come to Zion with songs</span><br/><span class=\"text Isa-35-10\">and everlasting joy upon their heads:</span><br/><span class=\"text Isa-35-10\">they shall obtain joy and gladness,</span><br/><span class=\"text Isa-35-10\">and sorrow and sighing shall flee away.</span></p></div> </div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"First Canticle","lines":[{"line_type":"heading","content":"MAGNIFICAT"},{"line_type":"subheading","content":"The Song of Mary"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"My soul magnifies the Lord, *"},{"line_type":"congregation","content":"and my spirit rejoices in God my Savior;"},{"line_type":"congregation","content":"For he has regarded *"},{"line_type":"congregation","content":"the lowliness of his handmaiden."},{"line_type":"congregation","content":"For behold, from now on, *"},{"line_type":"congregation","content":"all generations will call me blessed;"},{"line_type":"congregation","content":"For he that is mighty has magnified me, *"},{"line_type":"congregation","content":"and holy is his Name."},{"line_type":"congregation","content":"And his mercy is on those who fear him, *"},{"line_type":"congregation","content":"throughout all generations."},{"line_type":"congregation","content":"He has shown the strength of his arm; *"},{"line_type":"congregation","content":"he has scattered the proud in the imagination of their hearts."},{"line_type":"congregation","content":"He has brought down the mighty from their thrones, *"},{"line_type":"congregation","content":"and has exalted the humble and meek."},{"line_type":"congregation","content":"He has filled the hungry with good things, *"},{"line_type":"congregation","content":"and the rich he has sent empty away."},{"line_type":"congregation","content":"He, remembering his mercy, has helped his servant Israel, *"},{"line_type":"congregation","content":"as he promised to our fathers, Abraham and his seed for ever."},{"line_type":"citation","content":"LUKE 1:46-55"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Second Reading","lines":[{"line_type":"heading","content":"The Second Lesson"},{"line_type":"subheading","content":"Luke 5:17-39"},{"line_type":"reader","content":"A reading from the Gospel of our Lord Jesus Christ according to St. Luke, beginning with the fifth chapter, the seventeenth verse"},{"line_type":"spacer","content":""},{"line_type":"html","content":"<span data-line-id='secondreading_92bd0868-8950-5b16-aa63-bd1066616e8a'></span><div class=\"passage-content passage-class-0\"><div class=\"version-AKJV result-text-style-normal text-html\">\n<p><span class=\"text Luke-5-17\" id=\"en-AKJV-25125\"><sup class=\"versenum\">17\u00a0</sup>And it came to pass on a certain day, as he was teaching, that there were Pharisees and doctors of the law sitting by, which were come out of every town of Galilee, and Jud\u00e6a, and Jerusalem: and the power of the Lord was present to heal them. </span> <span class=\"text Luke-5-18\" id=\"en-AKJV-25126\"><sup class=\"versenum\">18\u00a0</sup>And, behold, men brought in a bed a man which was taken with a palsy: and they sought means to bring him in, and to lay him before him. </span> <span class=\"text Luke-5-19\" id=\"en-AKJV-25127\"><sup class=\"versenum\">19\u00a0</sup>And when they could not find by what way they might bring him in because of the multitude, they went upon the housetop, and let him down through the tiling with his couch into the midst before Jesus. </span> <span class=\"text Luke-5-20\" id=\"en-AKJV-25128\"><sup class=\"versenum\">20\u00a0</sup>And when he saw their faith, he said unto him, Man, thy sins are forgiven thee.</span></p><span data-line-id='secondreading_c8124c9a-f877-59d7-a478-3431ab7f5d2c'></span> <p><span class=\"text Luke-5-21\" id=\"en-AKJV-25129\"><sup class=\"versenum\">21\u00a0</sup>And the scribes and the Pharisees began to reason, saying, Who is this which speaketh blasphemies? Who can forgive sins, but God alone? </span> <span class=\"text Luke-5-22\" id=\"en-AKJV-25130\"><sup class=\"versenum\">22\u00a0</sup>But when Jesus perceived their thoughts, he answering said unto them, What reason ye in your hearts? </span> <span class=\"text Luke-5-23\" id=\"en-AKJV-25131\"><sup class=\"versenum\">23\u00a0</sup>Whether is easier, to say, Thy sins be forgiven thee; or to say, Rise up and walk? </span> <span class=\"text Luke-5-24\" id=\"en-AKJV-25132\"><sup class=\"versenum\">24\u00a0</sup>But that ye may know that the Son of man hath power upon earth to forgive sins, (he said unto the sick of the palsy,) I say unto thee, Arise, and take up thy couch, and go into thine house. </span> <span class=\"text Luke-5-25\" id=\"en-AKJV-25133\"><sup class=\"versenum\">25\u00a0</sup>And immediately he rose up before them, and took up that whereon he lay, and departed to his own house, glorifying God. </span> <span class=\"text Luke-5-26\" id=\"en-AKJV-25134\"><sup class=\"versenum\">26\u00a0</sup>And they were all amazed, and they glorified God, and were filled with fear, saying, We have seen strange things to day.</span></p><span data-line-id='secondreading_2d368f1b-dbbb-567c-a24e-c99e86e2481c'></span> <p><span class=\"text Luke-5-27\" id=\"en-AKJV-25135\"><sup class=\"versenum\">27\u00a0</sup>And after these things he went forth, and saw a publican, named Levi, sitting at the receipt of custom: and he said unto him, Follow me. </span> <span class=\"text Luke-5-28\" id=\"en-AKJV-25136\"><sup class=\"versenum\">28\u00a0</sup>And he left all, rose up, and followed him. </span> <span class=\"text Luke-5-29\" id=\"en-AKJV-25137\"><sup class=\"versenum\">29\u00a0</sup>And Levi made him a great feast in his own house: and there was a great company of publicans and of others that sat down with them. </span> <span class=\"text Luke-5-30\" id=\"en-AKJV-25138\"><sup class=\"versenum\">30\u00a0</sup>But their scribes and Pharisees murmured against his disciples, saying, Why do ye eat and drink with publicans and sinners? </span> <span class=\"text Luke-5-31\" id=\"en-AKJV-25139\"><sup class=\"versenum\">31\u00a0</sup>And Jesus answering said unto them, They that are whole need not a physician; but they that are sick. </span> <span class=\"text Luke-5-32\" id=\"en-AKJV-25140\"><sup class=\"versenum\">32\u00a0</sup>I came not to call the righteous, but sinners to repentance.</span></p><span data-line-id='secondreading_229f6670-dcdd-567c-b22b-e9728f20dd78'></span> <p><span class=\"text Luke-5-33\" id=\"en-AKJV-25141\"><sup class=\"versenum\">33\u00a0</sup>And they said unto him, Why do the disciples of John fast often, and make prayers, and likewise the disciples of the Pharisees; but thine eat and drink? </span> <span class=\"text Luke-5-34\" id=\"en-AKJV-25142\"><sup class=\"versenum\">34\u00a0</sup>And he said unto them, Can ye make the children of the bridechamber fast, while the bridegroom is with them? </span> <span class=\"text Luke-5-35\" id=\"en-AKJV-25143\"><sup class=\"versenum\">35\u00a0</sup>But the days will come, when the bridegroom shall be taken away from them, and then shall they fast in those days.</span></p><span data-line-id='secondreading_457aa428-96d6-5a10-b521-7efcb00673f1'></span> <p><span class=\"text Luke-5-36\" id=\"en-AKJV-25144\"><sup class=\"versenum\">36\u00a0</sup>And he spake also a parable unto them; No man putteth a piece of a new garment upon an old; if otherwise, then both the new maketh a rent, and the piece that was taken out of the new agreeth not with the old. </span> <span class=\"text Luke-5-37\" id=\"en-AKJV-25145\"><sup class=\"versenum\">37\u00a0</sup>And no man putteth new wine into old bottles; else the new wine will burst the bottles, and be spilled, and the bottles shall perish. </span> <span class=\"text Luke-5-38\" id=\"en-AKJV-25146\"><sup class=\"versenum\">38\u00a0</sup>But new wine must be put into new bottles; and both are preserved. </span> <span class=\"text Luke-5-39\" id=\"en-AKJV-25147\"><sup class=\"versenum\">39\u00a0</sup>No man also having drunk old wine straightway desireth new: for he saith, The old is better.</span></p>\n</div>\n</div>"},{"line_type":"spacer","content":""},{"line_type":"reader","content":"The Word of the Lord."},{"line_type":"congregation","content":"Thanks be to God."}]},{"name":"Second Canticle","lines":[{"line_type":"heading","content":"NUNC DIMITTIS"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The following Canticle is sung or said, all standing"},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"citation","content":"LUKE 2:29-32"},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"The Apostle's Creed","lines":[{"line_type":"heading","content":"The Apostles' Creed"},{"line_type":"rubric","content":"Officiant and People together, all standing"},{"line_type":"congregation","content":"I believe in God, the Father almighty,"},{"line_type":"congregation","content":"creator of heaven and earth."},{"line_type":"congregation","content":"I believe in Jesus Christ, his only Son, our Lord."},{"line_type":"congregation","content":"He was conceived by the Holy Spirit"},{"line_type":"congregation","content":"and born of the Virgin Mary."},{"line_type":"congregation","content":"He suffered under Pontius Pilate,"},{"line_type":"congregation","content":"was crucified, died, and was buried."},{"line_type":"congregation","content":"He descended to the dead."},{"line_type":"congregation","content":"On the third day he rose again."},{"line_type":"congregation","content":"He ascended into heaven,"},{"line_type":"congregation","content":"and is seated at the right hand of the Father."},{"line_type":"congregation","content":"He will come again to judge the living and the dead."},{"line_type":"congregation","content":"I believe in the Holy Spirit,"},{"line_type":"congregation","content":"the holy catholic Church,"},{"line_type":"congregation","content":"the communion of saints,"},{"line_type":"congregation","content":"the forgiveness of sins,"},{"line_type":"congregation","content":"the resurrection of the body,"},{"line_type":"congregation","content":"and the life everlasting. Amen."}]},{"name":"The Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"The Lord be with you.","preface":"Officiant"},{"line_type":"congregation_dialogue","content":"And with your spirit.","preface":"People"},{"line_type":"leader_dialogue","content":"Let us pray.","preface":"Officiant"},{"line_type":"rubric","content":"The People kneel or stand."},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"heading","content":"The Suffrages"},{"line_type":"leader_dialogue","content":"O Lord, show your mercy upon us;"},{"line_type":"congregation_dialogue","content":"And grant us your salvation."},{"line_type":"leader_dialogue","content":"O Lord, guide those who govern us"},{"line_type":"congregation_dialogue","content":"And lead us in the way of justice and truth."},{"line_type":"leader_dialogue","content":"Clothe your ministers with righteousness"},{"line_type":"congregation_dialogue","content":"And let your people sing with joy."},{"line_type":"leader_dialogue","content":"O Lord, save your people"},{"line_type":"congregation_dialogue","content":"And bless your inheritance."},{"line_type":"leader_dialogue","content":"Give peace in our time, O Lord"},{"line_type":"congregation_dialogue","content":"And defend us by your mighty power."},{"line_type":"leader_dialogue","content":"Let not the needy, O Lord, be forgotten"},{"line_type":"congregation_dialogue","content":"Nor the hope of the poor be taken away."},{"line_type":"leader_dialogue","content":"Create in us clean hearts, O God"},{"line_type":"congregation_dialogue","content":"And take not your Holy Spirit from us."}]},{"name":"Collect(s) of the Day","lines":[{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"The Last Sunday after Pentecost: Christ the King"},{"line_type":"leader","content":"Almighty and everlasting God, whose will it is to restore all things in your well-beloved Son, the King of kings and Lord of lords: Mercifully grant that the peoples of the earth, divided and enslaved by sin, may be freed and brought together under his most gracious rule; who lives and reigns with you and the Holy Spirit, one God, now and for ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"Collect of the Day"},{"line_type":"subheading","content":"Cecilia, Martyr at Rome, c. 230"},{"line_type":"leader","content":"Almighty God, you gave your servant Cecilia boldness to confess the Name of our Savior Jesus Christ before the rulers of this world, and courage to die for this faith: Grant that we may always be ready to give a reason for the hope that is in us, and to suffer gladly for the sake of our Lord Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, for ever and ever."},{"line_type":"congregation","content":"Amen."}]},{"name":"Additional Collects","lines":[{"line_type":"heading","content":"A Collect for Resurrection Hope"},{"line_type":"subheading","content":"Sunday"},{"line_type":"leader","content":"Lord God, whose Son our Savior Jesus Christ triumphed over the powers of death and prepared for us our place in the new Jerusalem: Grant that we, who have this day given thanks for his resurrection, may praise you in that City of which he is the light, and where he lives and reigns for ever and ever."},{"line_type":"congregation","content":"Amen."},{"line_type":"heading","content":"A Prayer for Mission"},{"line_type":"leader","content":"O God, you manifest in your servants the signs of your presence: Send forth upon us the Spirit of love, that in companionship with one another your abounding grace may increase among us; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."}]},{"name":"Intercessions, Thanksgivings, and Praise","lines":[{"line_type":"heading","content":"Intercessions, Thanksgivings, and Praise"},{"line_type":"rubric","content":"The Officiant may invite the People to offer intercessions and thanksgivings."},{"line_type":"rubric","content":"A hymn or anthem may be sung."},{"line_type":"speaker","content":"Let us pause to offer our own intercessions and thanksgivings."}]},{"name":"Final Prayers","lines":[{"line_type":"heading","content":"The General Thanksgiving"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Almighty God, Father of all mercies,"},{"line_type":"congregation","content":"we your unworthy servants give you humble thanks"},{"line_type":"congregation","content":"for all your goodness and loving-kindness"},{"line_type":"congregation","content":"to us and to all whom you have made."},{"line_type":"congregation","content":"We bless you for our creation, preservation,"},{"line_type":"congregation","content":"and all the blessings of this life;"},{"line_type":"congregation","content":"but above all for your immeasurable love"},{"line_type":"congregation","content":"in the redemption of the world by our Lord Jesus Christ;"},{"line_type":"congregation","content":"for the means of grace, and for the hope of glory."},{"line_type":"congregation","content":"And, we pray, give us such an awareness of your mercies,"},{"line_type":"congregation","content":"that with truly thankful hearts we may show forth your praise,"},{"line_type":"congregation","content":"not only with our lips, but in our lives,"},{"line_type":"congregation","content":"by giving up our selves to your service,"},{"line_type":"congregation","content":"and by walking before you"},{"line_type":"congregation","content":"in holiness and righteousness all our days;"},{"line_type":"congregation","content":"Through Jesus Christ our Lord,"},{"line_type":"congregation","content":"to whom, with you and the Holy Spirit,"},{"line_type":"congregation","content":"be honor and glory throughout all ages. Amen."},{"line_type":"heading","content":"A Prayer of St. John Chrysostom"},{"line_type":"leader","content":"Almighty God, you have given us grace at this time, with one accord to make our common supplications to you; and you have promised through your well-beloved Son that when two or three are gathered together in his Name you will grant their requests: Fulfill now, O Lord, our desires and petitions as may be best for us; granting us in this world knowledge of your truth, and in the age to come life everlasting."},{"line_type":"congregation","content":"Amen."}]},{"name":"Dismissal","lines":[{"line_type":"heading","content":"Dismissal and Grace"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Spirit, be with us all evermore."},{"line_type":"congregation","content":"Amen."},{"line_type":"citation","content":"2 CORINTHIANS 13:14"}]}],"compline":[{"name":"Opening Sentence","lines":[{"line_type":"heading","content":"Opening Sentence"},{"line_type":"rubric","content":"The Officiant begins:"},{"line_type":"leader_dialogue","content":"The Lord Almighty grant us a peaceful night and a perfect end."},{"line_type":"congregation_dialogue","content":"Amen."},{"line_type":"leader_dialogue","content":"Our help is in the Name of the Lord;"},{"line_type":"congregation_dialogue","content":"The maker of heaven and earth."}]},{"name":"Confession","lines":[{"line_type":"heading","content":"Confession of Sin"},{"line_type":"rubric","content":"The Officiant continues"},{"line_type":"leader_dialogue","content":"Let us humbly confess our sins unto Almighty God."},{"line_type":"rubric","content":"Silence may be kept. The Officiant and People then say"},{"line_type":"congregation","content":"Almighty God and Father, we confess to you,"},{"line_type":"congregation","content":"to one another, and to the whole company of heaven,"},{"line_type":"congregation","content":"that we have sinned, through our own fault,"},{"line_type":"congregation","content":"in thought, and word, and deed, and in what we have left undone."},{"line_type":"congregation","content":"For the sake of your Son our Lord Jesus Christ,"},{"line_type":"congregation","content":"have mercy upon us, forgive us our sins,"},{"line_type":"congregation","content":"and by the power of your Holy Spirit,"},{"line_type":"congregation","content":"raise us up to serve you in newness of life,"},{"line_type":"congregation","content":"to the glory of your Name. Amen."},{"line_type":"rubric","content":"The Officiant alone says"},{"line_type":"leader","content":"May almighty God grant us forgiveness of all our sins, and the grace and comfort of the Holy Spirit."},{"line_type":"congregation","content":"Amen."}]},{"name":"Invitatory","lines":[{"line_type":"heading","content":"Invitatory"},{"line_type":"leader_dialogue","content":"O God, make speed to save us;"},{"line_type":"congregation_dialogue","content":"O Lord, make haste to help us."},{"line_type":"leader_dialogue","content":"Glory be to the Father, and to the Son, and to the Holy Spirit;"},{"line_type":"congregation_dialogue","content":"As it was in the beginning, is now, and ever shall be, world without end. Amen. Alleluia."}]},{"name":"Psalms","lines":[{"line_type":"heading","content":"The Psalms"},{"line_type":"heading","content":"Psalm 4"},{"line_type":"subheading","content":"Cum invocarem"},{"line_type":"leader","content":"Hear me when I call, O God of my righteousness; *","preface":1},{"line_type":"leader","content":"you set me free when I was in trouble; have mercy upon me, and hear my prayer."},{"line_type":"congregation","content":"O you children of men, how long will you blaspheme my honor, *","preface":2},{"line_type":"congregation","content":"and have such pleasure in vanity, and seek after falsehood?"},{"line_type":"leader","content":"Know this also, that the L\u1d0f\u0280\u1d05 has chosen for himself the one that is godly; *","preface":3},{"line_type":"leader","content":"when I call upon the L\u1d0f\u0280\u1d05, he will hear me."},{"line_type":"congregation","content":"Stand in awe, and sin not; *","preface":4},{"line_type":"congregation","content":"commune with your own heart upon your bed, and be still."},{"line_type":"leader","content":"Offer the sacrifice of righteousness *","preface":5},{"line_type":"leader","content":"and put your trust in the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"There are many that say, \u201cWho will show us any good?\u201d *","preface":6},{"line_type":"congregation","content":"L\u1d0f\u0280\u1d05, lift up the light of your countenance upon us."},{"line_type":"leader","content":"You have put gladness in my heart, *","preface":7},{"line_type":"leader","content":"more than when others\u2019 grain and wine and oil increased."},{"line_type":"congregation","content":"I will lay me down in peace, and take my rest; *","preface":8},{"line_type":"congregation","content":"for you, L\u1d0f\u0280\u1d05, only, make me dwell in safety."},{"line_type":"heading","content":"Psalm 31:1-6"},{"line_type":"subheading","content":"In te, Domine, speravi"},{"line_type":"leader","content":"In you, O L\u1d0f\u0280\u1d05, have I put my trust; *","preface":1},{"line_type":"leader","content":"let me never be put to confusion; deliver me in your righteousness."},{"line_type":"congregation","content":"Bow down your ear to me, *","preface":2},{"line_type":"congregation","content":"make haste to deliver me,"},{"line_type":"leader","content":"And be my strong rock and house of defense, *","preface":3},{"line_type":"leader","content":"that you may save me."},{"line_type":"congregation","content":"For you are my strong rock and my castle; *","preface":4},{"line_type":"congregation","content":"be also my guide, and lead me for your Name\u2019s sake."},{"line_type":"leader","content":"Draw me out of the net that they have laid secretly for me, *","preface":5},{"line_type":"leader","content":"for you are my strength."},{"line_type":"congregation","content":"Into your hands I commend my spirit, *","preface":6},{"line_type":"congregation","content":"for you have redeemed me, O L\u1d0f\u0280\u1d05, O God of truth."},{"line_type":"heading","content":"Psalm 91"},{"line_type":"subheading","content":"Qui habitat"},{"line_type":"leader","content":"Whoever dwells under the defense of the Most High *","preface":1},{"line_type":"leader","content":"shall abide under the shadow of the Almighty."},{"line_type":"congregation","content":"I will say unto the L\u1d0f\u0280\u1d05, \u201cYou are my refuge and my stronghold, *","preface":2},{"line_type":"congregation","content":"my God in whom I will trust.\u201d"},{"line_type":"leader","content":"For he shall deliver you from the snare of the hunter *","preface":3},{"line_type":"leader","content":"and from the deadly pestilence."},{"line_type":"congregation","content":"He shall defend you under his wings, and you shall be safe under his feathers; *","preface":4},{"line_type":"congregation","content":"his faithfulness and truth shall be your shield and buckler."},{"line_type":"leader","content":"You shall not be afraid of any terror by night, *","preface":5},{"line_type":"leader","content":"nor of the arrow that flies by day,"},{"line_type":"congregation","content":"Of the pestilence that walks in darkness, *","preface":6},{"line_type":"congregation","content":"nor of the sickness that destroys at noonday."},{"line_type":"leader","content":"A thousand shall fall beside you, and ten thousand at your right hand, *","preface":7},{"line_type":"leader","content":"but it shall not come near you."},{"line_type":"congregation","content":"Indeed, with your eyes you shall behold *","preface":8},{"line_type":"congregation","content":"and see the reward of the ungodly."},{"line_type":"leader","content":"Because you have said, \u201cThe L\u1d0f\u0280\u1d05 is my refuge,\u201d *","preface":9},{"line_type":"leader","content":"and have made the Most High your stronghold,"},{"line_type":"congregation","content":"There shall no evil happen to you, *","preface":10},{"line_type":"congregation","content":"neither shall any plague come near your dwelling."},{"line_type":"leader","content":"For he shall give his angels charge over you, *","preface":11},{"line_type":"leader","content":"to keep you in all your ways."},{"line_type":"congregation","content":"They shall bear you in their hands, *","preface":12},{"line_type":"congregation","content":"that you hurt not your foot against a stone."},{"line_type":"leader","content":"You shall tread upon the lion and adder; *","preface":13},{"line_type":"leader","content":"the young lion and the serpent you shall trample under your feet."},{"line_type":"congregation","content":"\u201cBecause he has set his love upon me, therefore I will deliver him; *","preface":14},{"line_type":"congregation","content":"I will lift him up, because he has known my Name."},{"line_type":"leader","content":"He shall call upon me, and I will hear him; *","preface":15},{"line_type":"leader","content":"indeed, I am with him in trouble; I will deliver him and bring him honor."},{"line_type":"congregation","content":"With long life I will satisfy him, *","preface":16},{"line_type":"congregation","content":"and show him my salvation.\u201d"},{"line_type":"heading","content":"Psalm 134"},{"line_type":"subheading","content":"Ecce nunc"},{"line_type":"leader","content":"Behold now, praise the L\u1d0f\u0280\u1d05, *","preface":1},{"line_type":"leader","content":"all you servants of the L\u1d0f\u0280\u1d05,"},{"line_type":"congregation","content":"You that stand by night in the house of the L\u1d0f\u0280\u1d05, *","preface":2},{"line_type":"congregation","content":"even in the courts of the house of our God."},{"line_type":"leader","content":"Lift up your hands in the sanctuary *","preface":3},{"line_type":"leader","content":"and sing praises unto the L\u1d0f\u0280\u1d05."},{"line_type":"congregation","content":"The L\u1d0f\u0280\u1d05 who made heaven and earth *","preface":4},{"line_type":"congregation","content":"give you blessing out of Zion."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."}]},{"name":"Scripture","lines":[{"line_type":"heading","content":"The Reading"},{"line_type":"leader","content":"Now may the God of peace who brought again from the dead our Lord Jesus, the great shepherd of the sheep, by the blood of the eternal covenant, equip you with everything good that you may do his will, working in us that which is pleasing in his sight, through Jesus Christ, to whom be glory forever and ever. Amen."},{"line_type":"citation","content":"HEBREWS 13:20-21"},{"line_type":"leader_dialogue","content":"The Word of the Lord"},{"line_type":"congregation_dialogue","content":"Thanks be to God."}]},{"name":"Prayers","lines":[{"line_type":"heading","content":"The Prayers"},{"line_type":"leader_dialogue","content":"Into your hands, O Lord, I commend my spirit;"},{"line_type":"congregation_dialogue","content":"For you have redeemed me, O Lord, O God of truth."},{"line_type":"leader_dialogue","content":"Keep me, O Lord, as the apple of your eye;"},{"line_type":"congregation_dialogue","content":"Hide me under the shadow of your wings."},{"line_type":"spacer","content":""},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"congregation","content":"Christ, have mercy upon us"},{"line_type":"leader","content":"Lord, have mercy upon us"},{"line_type":"rubric","content":"Officiant and People"},{"line_type":"congregation","content":"Our Father, who art in heaven,"},{"line_type":"congregation","content":"hallowed be thy Name,"},{"line_type":"congregation","content":"thy kingdom come,"},{"line_type":"congregation","content":"thy will be done,"},{"line_type":"congregation","content":"on earth as it is in heaven."},{"line_type":"congregation","content":"Give us this day our daily bread."},{"line_type":"congregation","content":"And forgive us our trespasses,"},{"line_type":"congregation","content":"as we forgive those"},{"line_type":"congregation","content":"who trespass against us."},{"line_type":"congregation","content":"And lead us not into temptation,"},{"line_type":"congregation","content":"but deliver us from evil."},{"line_type":"congregation","content":"For thine is the kingdom,"},{"line_type":"congregation","content":"and the power, and the glory,"},{"line_type":"congregation","content":"for ever and ever. Amen."},{"line_type":"spacer","content":""},{"line_type":"leader_dialogue","content":"O Lord, hear our prayer"},{"line_type":"congregation_dialogue","content":"And let our cry come to you."},{"line_type":"leader_dialogue","content":"Let us pray."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Evening"},{"line_type":"leader","content":"Visit this place, O Lord, and drive far from it all snares of the enemy; let your holy angels dwell with us to preserve us in peace; and let your blessing be upon us always; through Jesus Christ our Lord."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Aid Against Peril"},{"line_type":"leader","content":"Lighten our darkness, we beseech you, O Lord; and by your great mercy defend us from all perils and dangers of this night; for the love of your only Son, our Savior Jesus Christ."},{"line_type":"congregation","content":"Amen."},{"line_type":"spacer","content":""},{"line_type":"subheading","content":"A Collect for Mission"},{"line_type":"leader","content":"Keep watch, dear Lord, with those who work, or watch, or weep this night, and give your angels charge over those who sleep. Tend the sick, Lord Christ; give rest to the weary, bless the dying, soothe the suffering, pity the afflicted, shield the joyous; and all for your love\u2019s sake."},{"line_type":"congregation","content":"Amen."}]},{"name":"Nunc Dimittis","lines":[{"line_type":"heading","content":"Nunc Dimittis"},{"line_type":"subheading","content":"The Song of Simeon"},{"line_type":"rubric","content":"The Officiant and People say or sing the Song of Simeon with this Antiphon, all standing"},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Lord, now let your servant depart in peace, *"},{"line_type":"congregation","content":"according to your word."},{"line_type":"congregation","content":"For my eyes have seen your salvation, *"},{"line_type":"congregation","content":"which you have prepared before the face of all people;"},{"line_type":"congregation","content":"To be a light to lighten the Gentiles, *"},{"line_type":"congregation","content":"and to be the glory of your people Israel."},{"line_type":"congregation","content":"Glory be to the Father, and to the Son, and to the Holy Spirit; *"},{"line_type":"congregation","content":"as it was in the beginning, is now, and ever shall be, world without end. Amen."},{"line_type":"spacer","content":""},{"line_type":"congregation","content":"Guide us waking, O Lord, and guard us sleeping; that awake we may watch with Christ, and asleep we may rest in peace."}]},{"name":"Conclusion","lines":[{"line_type":"heading","content":"The Dismissal"},{"line_type":"leader_dialogue","content":"Let us bless the Lord."},{"line_type":"congregation_dialogue","content":"Thanks be to God."},{"line_type":"rubric","content":"The Officiant concludes with the following"},{"line_type":"leader_dialogue","content":"The almighty and merciful Lord, Father, Son, and Holy Spirit, bless us and keep us, this night and evermore."},{"line_type":"congregation_dialogue","content":"Amen."}]}]}};
